let databaseQuery='',databaseKind='all',databaseOnly='',databasePage=0;
const databaseTypes={players:'Jogadores',clubs:'Clubes',staff:'Staff',competitions:'Competições'};
function openDatabaseSearch(type='all',only=''){databaseKind=type;databaseOnly=only;databaseQuery='';databasePage=0;view='Pesquisa global';render();}
function openFilteredPlayers(filters={}){selectedPlayers.clear();playerFilters={...defaultPlayerFilters(),...filters};playerPage=0;view='Todos os jogadores';render();}
function mountDatabaseHealth(){
 const h=Documentary.health(master),metrics=[['players','Jogadores',h.players],['clubs','Clubes',h.clubs],['staff','Staff',h.staff],['competitions','Competições',h.competitions],['noPhoto','Sem fotografia',h.noPhoto],['noBirth','Sem nascimento',h.noBirth],['noClub','Sem clube',h.noClub],['noContract','Contrato incompleto',h.noContract],['unverified','Jogadores por verificar',h.unverified],['noLogo','Clubes sem logótipo',h.noLogo],['duplicates','Possíveis duplicados',h.duplicateIds.size],['warnings','Avisos de coerência',h.warnings.length]];
 $('app').insertAdjacentHTML('afterbegin',`<section class="panel database-health"><div class="panel-head"><div><span class="eyebrow">BASE DE DADOS MESTRE</span><h2>Saúde da Base de Dados</h2></div><button id="healthSearch">Pesquisar em todos os registos</button></div><div class="health-completeness"><div><strong>${h.percent}%</strong><span>Completude documental dos jogadores</span></div><progress max="100" value="${h.percent}" aria-label="Completude documental dos jogadores">${h.percent}%</progress><p class="muted">Presença de dados, não garantia de exactidão. Contratos só contam para jogadores associados a clubes e não retirados; fontes de selecções só contam quando há internacionalizações registadas. Os valores do jogo e estatísticas simuladas não entram neste indicador.</p></div><div class="health-grid">${metrics.map(([key,label,n])=>`<button class="health-metric" data-health="${key}"><strong>${n}</strong><span>${label}</span></button>`).join('')}</div><p class="muted">Duplicados: jogadores com o mesmo nome completo (ou conhecido) e nascimento. Avisos não alteram dados. Um registo incompleto pode ser correcto.</p></section>`);
 $('healthSearch').onclick=()=>openDatabaseSearch();
 const filters={players:{},noPhoto:{photo:'missing'},noBirth:{birth:'missing'},noClub:{club:'free'},noContract:{contract:'missing'},unverified:{verification:'Por verificar'}};
 document.querySelectorAll('[data-health]').forEach(b=>b.onclick=()=>{const key=b.dataset.health;if(key in filters)openFilteredPlayers(filters[key]);else if(key==='noLogo')openDatabaseSearch('clubs','noLogo');else if(key==='duplicates'||key==='warnings')openDatabaseSearch('all',key);else openDatabaseSearch(key);});
}
function renderDatabaseSearch(){
 $('app').innerHTML=`<section class="panel"><h2>Pesquisa global</h2><div class="search-filters"><label class="search-wide">Nome, clube, cargo ou país<input id="global-query" type="search" maxlength="200" value="${esc(databaseQuery)}" placeholder="Pesquisar jogadores, clubes, staff e competições…"></label><label>Tipo de registo<select id="global-kind"><option value="all">Todos</option>${Object.entries(databaseTypes).map(([key,label])=>`<option value="${key}" ${databaseKind===key?'selected':''}>${label}</option>`).join('')}</select></label><label>Diagnóstico<select id="global-only">${[['','Todos os registos'],['noLogo','Clubes sem logótipo'],['duplicates','Possíveis jogadores duplicados'],['warnings','Registos com avisos']].map(([key,label])=>`<option value="${key}" ${databaseOnly===key?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="toolbar"><button id="global-clear">Limpar filtros</button><button id="global-players">Filtros avançados de jogadores</button></div><p id="global-count" role="status"></p><div id="global-results"></div><div id="global-pages" class="search-pages"></div></section>`;
 for(const [id,key] of [['global-query','query'],['global-kind','kind'],['global-only','only']])$(id).addEventListener(key==='query'?'input':'change',e=>{if(key==='query')databaseQuery=e.target.value;if(key==='kind')databaseKind=e.target.value;if(key==='only')databaseOnly=e.target.value;databasePage=0;drawDatabaseResults();});
 $('global-clear').onclick=()=>openDatabaseSearch();$('global-players').onclick=()=>openFilteredPlayers();drawDatabaseResults();
}
function drawDatabaseResults(){
 const diagnostic=Documentary.diagnostics(master),warnings=new Map();for(const w of diagnostic.warnings){const key=w.type+':'+w.id;if(!warnings.has(key))warnings.set(key,[]);warnings.get(key).push(w.message);}
 const rows=Documentary.globalSearch(master,databaseQuery,databaseKind).filter(r=>databaseOnly==='noLogo'?r.type==='clubs'&&!master.clubs.find(c=>c.id===r.id).logo:databaseOnly==='duplicates'?r.type==='players'&&diagnostic.duplicateIds.has(r.id):databaseOnly==='warnings'?warnings.has(r.type+':'+r.id):true);
 const pages=Math.max(1,Math.ceil(rows.length/50));databasePage=Math.min(databasePage,pages-1);
 $('global-count').textContent=rows.length+' registos'+(databaseOnly?' · Diagnóstico informativo; sem correcções automáticas.':'');
 $('global-results').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>TIPO</th><th>NOME</th><th>INFORMAÇÃO</th></tr></thead><tbody>${rows.slice(databasePage*50,databasePage*50+50).map(r=>`<tr><td>${databaseTypes[r.type]}</td><td><button class="player-name" data-global-type="${r.type}" data-global-id="${r.id}">${esc(r.name)}</button></td><td>${esc(r.detail)}${databaseOnly==='duplicates'?'<p class="diagnostic-note">Nome e nascimento coincidentes. Pode tratar-se de pessoas diferentes.</p>':''}${(warnings.get(r.type+':'+r.id)||[]).map(w=>`<p class="diagnostic-note">${esc(w)}</p>`).join('')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Não há registos com estes filtros.</p>';
 $('global-results').querySelectorAll('[data-global-id]').forEach(b=>b.onclick=()=>{const type=b.dataset.globalType,id=+b.dataset.globalId;if(type==='players')openPlayer(id);else if(type==='clubs')showClub(id);else if(type==='staff')edit('staff',id);else{view='Editor de competições';render();document.querySelector(`[data-competition-card="${id}"]`)?.scrollIntoView({block:'start'});}});
 $('global-pages').innerHTML=`<button id="global-prev" ${databasePage===0?'disabled':''}>Anterior</button><span>Página ${databasePage+1} de ${pages}</span><button id="global-next" ${databasePage===pages-1?'disabled':''}>Seguinte</button>`;
 $('global-prev').onclick=()=>{databasePage--;drawDatabaseResults();};$('global-next').onclick=()=>{databasePage++;drawDatabaseResults();};
}
